<script setup lang="ts">
import type{components}from'~/api/schema';import{unwrap}from'~/api/client';import{displayError}from'~/utils/errors';import{formatDate,formatRupiah,statusLabel}from'~/utils/format';
type Quote=components['schemas']['QuoteRequest'];definePageMeta({middleware:'auth'});const api=useMarketplaceApi();const portal=usePortal();const items=ref<Quote[]>([]);const pending=ref(true);const error=ref<unknown>();const filter=ref('ALL');const visible=computed(()=>filter.value==='ALL'?items.value:items.value.filter(x=>x.status===filter.value));
async function load(){pending.value=true;error.value=undefined;try{if(!portal.activeStore.value)await portal.loadStores();if(!portal.storeId.value)return;items.value=unwrap(await api.GET('/vendor/stores/{storeId}/quote-requests',{params:{path:{storeId:portal.storeId.value},query:{limit:100}},cache:'no-store'})).items;}catch(cause){error.value=cause;}finally{pending.value=false;}}watch(()=>portal.storeId.value,()=>{void load();});onMounted(()=>{void load();});useSeoMeta({title:'RFQ vendor — Niaga'});
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="vendor"/><div class="section-heading"><div><p class="eyebrow">Penawaran</p><h1>Inbox RFQ</h1></div><div class="form-actions"><StoreSwitcher/><select v-model="filter"><option value="ALL">Semua</option><option value="SUBMITTED">Menunggu respons</option><option value="OFFERED">Sudah ditawarkan</option><option value="REJECTED">Ditolak</option><option value="CLOSED">Ditutup</option></select></div></div><ApiState :pending="pending" :error="error?displayError(error):null" :empty="!pending&&!visible.length" empty-title="Tidak ada RFQ" @retry="load"><div class="order-list"><NuxtLink v-for="quote in visible" :key="quote.id" class="surface order-card" :to="`/vendor/rfq/${quote.id}`"><header><div><strong>RFQ {{ quote.id.slice(0,8) }}</strong><small>{{ formatDate(quote.created_at) }} · {{ quote.items.length }} SKU</small></div><span class="badge">{{ statusLabel(quote.status) }}</span></header><div v-for="version in quote.versions.slice(-1)" :key="version.id" class="summary-line"><span>Versi {{ version.version_no }}</span><strong>{{ formatRupiah(version.items.reduce((sum,x)=>sum+x.quantity*x.unit_price_gross,0)) }}</strong></div></NuxtLink></div></ApiState></main></template>
